A streaming CSV parser must handle two things at once: bounded memory and the RFC 4180 rules that make CSV context-sensitive. The hard part is that a quoted field may contain newlines, so line-oriented reading is insufficient. Below is a complete implementation, tests, and the tradeoff analysis.

## Design

The parser is a state machine with three states:

- `FIELD_START` — at the beginning of a field; determines whether the field is quoted.
- `UNQUOTED` — inside a plain field; a comma ends the field, a newline ends the record.
- `QUOTED` — inside a quoted field; only a closing quote ends the field. A doubled quote is an escaped literal quote; anything else, including a newline, is literal data.

The parser consumes one character at a time from a caller-supplied iterator. This keeps the core pure: it yields complete records and never touches I/O.

## Implementation

```python
from __future__ import annotations
from collections.abc import Iterator, Iterable

class CSVError(ValueError):
    pass

class RecordParser:
    """Parses a character stream into lists of field values."""

    def __init__(self, delimiter: str = ",", quote: str = '"') -> None:
        if len(delimiter) != 1 or len(quote) != 1:
            raise ValueError("delimiter and quote must be single characters")
        if delimiter == quote:
            raise ValueError("delimiter and quote must differ")
        self._delim = delimiter
        self._quote = quote

    def parse(self, chars: Iterable[str]) -> Iterator[list[str]]:
        fields: list[str] = []
        buf: list[str] = []

        def end_field() -> None:
            fields.append("".join(buf))
            buf.clear()

        def end_record() -> Iterator[list[str]]:
            end_field()
            return iter([fields[:]])

        state = "FIELD_START"
        for ch in chars:
            if state == "FIELD_START":
                if ch == self._quote:
                    state = "QUOTED"
                elif ch == self._delim:
                    end_field()
                elif ch in ("\n", "\r"):
                    yield from end_record()
                    state = "FIELD_START"
                    fields.clear()
                else:
                    buf.append(ch)
                    state = "UNQUOTED"
            elif state == "UNQUOTED":
                if ch == self._delim:
                    end_field()
                    state = "FIELD_START"
                elif ch == "\n":
                    yield from end_record()
                    state = "FIELD_START"
                    fields.clear()
                elif ch == "\r":
                    state = "CR_UNQUOTED"
                else:
                    buf.append(ch)
            elif state == "QUOTED":
                if ch == self._quote:
                    state = "QUOTE_IN_QUOTED"
                else:
                    buf.append(ch)
            elif state == "QUOTE_IN_QUOTED":
                if ch == self._quote:
                    buf.append(self._quote)
                    state = "QUOTED"
                elif ch == self._delim:
                    end_field()
                    state = "FIELD_START"
                elif ch == "\n":
                    yield from end_record()
                    state = "FIELD_START"
                    fields.clear()
                elif ch == "\r":
                    state = "CR_QUOTE_IN_QUOTED"
                else:
                    raise CSVError(
                        f"unexpected character {ch!r} after closing quote"
                    )
            elif state == "CR_UNQUOTED":
                if ch == "\n":
                    yield from end_record()
                    state = "FIELD_START"
                    fields.clear()
                else:
                    buf.append("\r")
                    buf.append(ch)
                    state = "UNQUOTED"
            elif state == "CR_QUOTE_IN_QUOTED":
                if ch == "\n":
                    yield from end_record()
                    state = "FIELD_START"
                    fields.clear()
                else:
                    raise CSVError(
                        f"unexpected character {ch!r} after closing quote"
                    )
            else:
                raise AssertionError(f"unknown state {state}")

        # End of input.
        if state in ("QUOTED", "CR_UNQUOTED"):
            raise CSVError("unexpected end of input inside quoted field")
        if state in ("UNQUOTED", "QUOTE_IN_QUOTED", "CR_QUOTE_IN_QUOTED"):
            yield from end_record()
        elif state == "FIELD_START" and fields:
            yield from end_record()
