    IN_FIELD = auto()
    IN_QUOTED = auto()
    QUOTE_IN_QUOTED = auto()

class CSVParseError(Exception):
    pass

def parse_csv(stream, delimiter=',', quotechar='"', strict=True):
    """Yield records (lists of strings) from a text stream."""
    state = CSVState.FIELD_START
    field = []
    record = []
    saw_any = False

    def end_field():
        record.append(''.join(field))
        field.clear()

    def end_record():
        end_field()
        result = list(record)
        record.clear()
        return result

    while True:
        chunk = stream.read(8192)
        if not chunk:
            break
        for ch in chunk:
            saw_any = True
            if state == CSVState.FIELD_START:
                if ch == quotechar:
                    state = CSVState.IN_QUOTED
                elif ch == delimiter:
                    end_field()
                elif ch in '\r\n':
                    yield end_record()
                    if ch == '\r':
                        # handle CRLF: skip the following \n
                        state = CSVState.FIELD_START
                        # need lookahead; see note below
                else:
                    field.append(ch)
                    state = CSVState.IN_FIELD
            elif state == CSVState.IN_FIELD:
                if ch == delimiter:
                    end_field()
                    state = CSVState.FIELD_START
                elif ch in '\r\n':
                    yield end_record()
                    state = CSVState.FIELD_START
                else:
                    field.append(ch)
            elif state == CSVState.IN_QUOTED:
                if ch == quotechar:
                    state = CSVState.QUOTE_IN_QUOTED
                else:
                    field.append(ch)
            elif state == CSVState.QUOTE_IN_QUOTED:
                if ch == quotechar:
                    field.append(quotechar)  # escaped quote
                    state = CSVState.IN_QUOTED
                elif ch == delimiter:
                    end_field()
                    state = CSVState.FIELD_START
                elif ch in '\r\n':
                    yield end_record()
                    state = CSVState.FIELD_START
