                    # lenient: treat the quote as data and continue
                    field.append(quotechar)
                    field.append(ch)
                    state = CSVState.IN_FIELD

    # end of input
    if state == CSVState.IN_QUOTED:
        raise CSVParseError("unexpected end of input inside quoted field")
    if field or record:
        yield end_record()
    elif not saw_any:
        return  # empty input yields nothing
