class SpscRing {
    static_assert((N & (N - 1)) == 0, "N must be power of 2");
    T buffer_[N];
    alignas(64) std::atomic<size_t> head_{0};   // consumer-owned
    alignas(64) std::atomic<size_t> tail_{0};   // producer-owned
public:
    bool push(const T& v) {
        size_t t = tail_.load(std::memory_order_relaxed);
        size_t h = head_.load(std::memory_order_acquire);
        if (t - h == N) return false;
        buffer_[t & (N - 1)] = v;
        tail_.store(t + 1, std::memory_order_release);
        return true;
    }
    bool pop(T& out) {
        size_t h = head_.load(std::memory_order_relaxed);
        size_t t = tail_.load(std::memory_order_acquire);
        if (t == h) return false;
        out = buffer_[h & (N - 1)];
        head_.store(h + 1, std::memory_order_release);
        return true;
    }
};
```

Note the `alignas(64)`: `head_` and `tail_` are on different cache lines to prevent false sharing—each core invalidating the other's cache line on every update.

